import { useState, type FormEvent } from 'react';
import { Alert, Button, Field, Input, Select, Stack, Switch } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLE_OPTIONS = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('viewer');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email);
  const showError = touched && !isValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvitedEmail(email);
    setEmail('');
    setTouched(false);
  };

  return (
    <Stack direction="column" gap="var(--jx-space-4)">
      {invitedEmail && (
        <Alert
          variant="success"
          title="Приглашение отправлено"
          dismissible
          onDismiss={() => setInvitedEmail(null)}
        >
          {`Мы пригласили ${invitedEmail} в команду.`}
        </Alert>
      )}

      <form onSubmit={handleSubmit} noValidate>
        <Stack direction="column" gap="var(--jx-space-4)">
          <Field
            label="Электронная почта"
            htmlFor="invite-email"
            hint="Укажите рабочий адрес — на него придёт ссылка-приглашение."
            error={showError ? 'Введите корректный адрес, например name@company.com' : undefined}
            invalid={showError}
            required
          >
            <Input
              id="invite-email"
              type="email"
              value={email}
              placeholder="name@company.com"
              invalid={showError}
              onChange={(event) => setEmail(event.target.value)}
              onBlur={() => setTouched(true)}
            />
          </Field>

          <Field label="Роль в команде" htmlFor="invite-role">
            <Select
              id="invite-role"
              value={role}
              options={ROLE_OPTIONS}
              onChange={(value: string) => setRole(value)}
            />
          </Field>

          <Switch
            checked={notify}
            label="Отправить уведомление"
            description="Участник получит письмо сразу после приглашения."
            onChange={(checked: boolean) => setNotify(checked)}
          />

          <Button type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </Button>
        </Stack>
      </form>
    </Stack>
  );
}

